"""Reuse a static prop's exact transform while its private input bits are unchanged."""

def optimize_proptransform(override):
    override('Actors/StaticProp.cs', [('private float rotation = 0;', 'private float rotation = 0;\n    private bool transformReady;\n    private int transformScaleBits, transformRotationBits;\n    private Matrix preparedTransform;'), ('Model.Transform = \n\t\t\tMatrix.CreateRotationY(rotation) *\n\t\t\tMatrix.CreateScale(0.2f * scale);', 'int scaleBits = BitConverter.SingleToInt32Bits(scale);\n        int rotationBits = BitConverter.SingleToInt32Bits(rotation);\n        if (!transformReady || scaleBits != transformScaleBits || rotationBits != transformRotationBits)\n        {\n            preparedTransform = Matrix.CreateRotationY(rotation) * Matrix.CreateScale(0.2f * scale);\n            transformScaleBits = scaleBits;\n            transformRotationBits = rotationBits;\n            transformReady = true;\n        }\n        // Keep the original assignment on every collection, even if another\n        // caller has overwritten the public model transform since the last one.\n        Model.Transform = preparedTransform;')])
